    let match;

    while ((match = regex.exec(corpus))) {
      const key = match[1];
      let value = match[2] || '';

      // Remove surrounding quotes from strings
      if (value.length > 1 && (value[0] === '"' || value[0] === "'")) {
        value = value.slice(1, -1);
      }

      // Expand newlines
      value = value.replace(/\\n/g, '\\n').replace(/\\r/g, '\\r');

      env[key] = value;

      // Set environment variable if it doesn't exist
